#!/bin/sh
# ncc_libm_exact: bit-exact sin/cos and helper math gate, run entirely in ncc.
#
# The corpus is checked in (src/tests/ncc_libm_*_corpus.txt); the guest C
# program is generated by tools/ncc_libm_gen.py, compiled and executed by ncc
# in raw NaN16. Every result is compared as 32 raw bits against the checked-in
# host-clang artifact src/tests/ncc_libm_exact.expected:
#
#   sin/cos reference: (float)sin((double)x) / (float)cos((double)x)
#   helpers          : sqrtf/fabsf/floorf/ceilf/truncf/roundf/fmodf
#
# Regenerate the expected file (host only, never in the guest path):
#   cc -O2 -ffp-contract=off -fno-fast-math tools/ncc_libm_ref.c \
#      -o "$TMPDIR/ncc_libm_ref" -lm
#   "$TMPDIR/ncc_libm_ref" src/tests/ncc_libm_corpus.txt \
#      src/tests/ncc_libm_unary_corpus.txt src/tests/ncc_libm_fmod_corpus.txt \
#      > src/tests/ncc_libm_exact.expected
set -e; cd "$(dirname "$0")/.."
T="${TMPDIR:-/tmp}/ncclibm.$$"; mkdir -p "$T"; trap 'rm -rf "$T"; rm -f src/tests/.ncc_libm_exact_test.nas' EXIT
python3 tools/ncc_libm_gen.py nas src/tests/.ncc_libm_exact_test.nas
awk -f tools/nmk.awk -v CMD=emit src/tests/.ncc_libm_exact_test.nas > "$T/a.nan"
./aarch64/android/nan_cli --img "$T/a.nan" --steps 1000000000 --serial > "$T/out" 2>"$T/err" || true
sed -e 's/^\[nan_cli\].*$//' -e '/^$/d' "$T/out" > "$T/got"
if diff -u src/tests/ncc_libm_exact.expected "$T/got"; then
  echo "ncc_libm_exact: PASS ($(grep -c '^s ' "$T/got") sin, $(grep -c '^c ' "$T/got") cos, $(grep -c '^fmod ' "$T/got") fmod exact bits)"
else
  echo "ncc_libm_exact: FAIL"; tail -2 "$T/err"; exit 1
fi
